ee:message.ee:set-payload:
%dw 2.0
output application/xml
---
{
    request: {
        control: {
            senderid: p("sage.senderId"),
            password: p("secure::sage.senderPassword"),
            controlid: uuid(),
            uniqueid: false,
            dtdversion: "3.0",
            includewhitespace: false
        },
        operation: {
            authentication: {
                sessionid: vars.sessionId
            },
            content: function @("controlid": uuid()): payload.POrders map (poOrder) -> {
    create_potransaction: {
            transactiontype: poOrder.Category,
            datecreated: {
                year: ((poOrder.POrderDate default "2026-10-01") as Date).year,
                month: ((poOrder.POrderDate default "2026-10-01") as Date).month,
                day: ((poOrder.POrderDate default "2026-10-01") as Date).day
            },
            vendorid: poOrder.VendorExternalRef default "",
            documentno: poOrder.POrderNumber default "",
            returnto: {
                contactname: poOrder.VendorCompanyName default ""
            },
            payto: {
                contactname: poOrder.VendorCompanyName default ""
            },
            projectid: poOrder.JobId default "",
            potransitems: {
                potransitem: poOrder.LineItems map {
                    itemid: $.ExternalRef default "",
                    itemdesc: $.Description default "",
                    quantity: $.Quantity default 0,
                    unit: "Box",
                    price: $.Estimate default 0,
                    projectid: $.JobId default "",
                    taskid: $.Activity default "",
                    costtypeid: $.CostCategory default "",
                }
            }
        }
}
        }
    }
}

%dw 2.0
output application/xml

var entityConfig = {

    vendor: {
        objectName: "VENDOR",
        operation: "read"
    }

}

var config = entityConfig[vars.entity]

---
{
    request: {
        control: {
            senderid: p("sage.senderId"),
            password: p("secure::sage.senderPassword"),
            controlid: uuid(),
            uniqueid: false,
            dtdversion: "3.0",
            includewhitespace: false
        },
        operation: {
            authentication: {
                sessionid: vars.sessionId
            },
            content: {
                function @(controlid: uuid()): {
                    read: {
                        object: config.objectName,
                        keys: vars.externalRef,
                        fields: "*"
                    }
                }
            }
        }
    }
}

%dw 2.0
output application/xml

var entityConfig = {
    vendor: {
        objectName: "VENDOR",
        operation: "update",
        data: {
            RECORDNO: vars.externalRef,
            VENDORID: vars.vendorId,
            DASH_VENDOR_ID: vars.dashVendorId
        }
    }
}

var config = entityConfig[vars.entity]

---
{
    request: {
        control: {
            senderid: p("sage.senderId"),
            password: p("secure::sage.senderPassword"),
            controlid: uuid(),
            uniqueid: false,
            dtdversion: "3.0",
            includewhitespace: false
        },
        operation: {
            authentication: {
                sessionid: vars.sessionId
            },
            content: {
                function @(controlid: uuid()): {
                    (config.operation): {
                        (config.objectName): config.data
                    }
                }
            }
        }
    }
}
